func (this *testMainClass) CheckIfSpecificTestIsChosen(methodArgv any) {
	if !func(a any) bool {
		for _, p := range []*any{&a} {
			for {
				switch (*p).(type) {
				case *string, *int64, *float64, *bool, *int, *[]string, *[]any, *map[string]any, *any:
					r := reflect.ValueOf(*p)
					_, again := (*p).(*any)
					if *p = nil; !r.IsNil() {
						*p = r.Elem().Interface()
					}
					if again && *p != nil {
						continue
					}
				case map[string]any, []any, []string:
					if reflect.ValueOf(*p).IsNil() {
						*p = nil
					}
				}
				break
			}
		}
		if t := reflect.TypeOf(a); t != nil && t.Kind() == reflect.Pointer && t.Elem().PkgPath() == "sync" && t.Elem().Name() == "Map" && reflect.ValueOf(a).IsNil() {
			return true
		}
		return a == nil
	}(methodArgv) {
		var testFileNames []string = ObjectKeys(this.TestFiles)
		var possibleMethodNames []string = func(a any, b string) []string {
			d := func(v any) any {
				for {
					switch p := v.(type) {
					case *any:
						if p == nil {
							return nil
						}
						v = *p
						continue
					case *string, *int64, *float64, *bool, *int, *[]string, *[]any, *map[string]any:
						if r := reflect.ValueOf(p); !r.IsZero() {
							return r.Elem().Interface()
						}
						return nil
					case map[string]any, []any, []string:
						if reflect.ValueOf(p).IsZero() {
							return nil
						}
					}
					return v
				}
			}
			x, ok := d(a).(string)
			if !ok {
				return nil
			}
			return (strings.Split)(x, b)
		}(methodArgv, ",") // i.e. `test.ts binance fetchBalance,fetchDeposits`
		if len(possibleMethodNames) >= 1 {
			for i := 0; i < len(testFileNames); i++ {
				var testFileName string = testFileNames[i]
				for j := 0; j < len(possibleMethodNames); j++ {
					var methodName string = possibleMethodNames[j]
					methodName = strings.Replace(methodName, "()", "", 1)
					if testFileName == methodName {
						AppendToArray(&this.OnlySpecificTests, testFileName)
					}
				}
			}
		}
	}
}
