func (this *testMainClass) WsRequestWasSent(exchange ccxt.ICoreExchange, url any, id any) any {
	var sentMessages any = GetWsSentMessages(exchange, url)
	for i := 0; i < GetArrayLength(sentMessages); i++ {
		if func(a, b any) bool {
			for _, p := range []*any{&a, &b} {
				for {
					switch (*p).(type) {
					case *string, *int64, *float64, *bool, *int, *[]string, *[]any, *map[string]any, *any:
						r := reflect.ValueOf(*p)
						_, again := (*p).(*any)
						if *p = nil; !r.IsNil() {
							*p = r.Elem().Interface()
						}
						if again && *p != nil {
							continue
						}
					case map[string]any, []any, []string:
						if reflect.ValueOf(*p).IsNil() {
							*p = nil
						}
					}
					break
				}
			}
			num := func(v any) (int64, float64, int) {
				switch n := v.(type) {
				case int:
					return int64(n), float64(n), 1
				case int64:
					return n, float64(n), 1
				case float64:
					return 0, n, 2
				}
				return 0, 0, 0
			}
			ia, fa, ka := num(a)
			ib, fb, kb := num(b)
			eq := (a == nil && b == nil) || (ka == 1 && kb == 1 && ia == ib) || (ka*kb > 1 && fa == fb)
			switch x := a.(type) {
			case bool, string:
				eq = x == b
			case uint8:
				switch y := b.(type) {
				case uint8:
					eq = x == y
				case int64:
					eq = int64(x) == y
				case float64:
					eq = float64(x) == y
				}
			}
			if t := reflect.TypeOf(a); t != nil && t.Kind() == reflect.Pointer && t.Elem().PkgPath() == "sync" && t.Elem().Name() == "Map" && reflect.ValueOf(a).IsNil() {
				eq = true
			}
			return eq
		}(exchange.SafeString(GetValue(sentMessages, i), "id"), id) {
			return true
		}
	}
	return false
}
