func (this *testMainClass) watchAndAssertSequenceBody(ch chan ccxt.AsyncResult[any], exchange ccxt.ICoreExchange, url any, method any, input any, skipKeys any, expectedResults any) any {
	defer close(ch)
	defer ReturnPanicError(ch)

	{
		func(this *testMainClass) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *testMainClass) any {
						// catch block:
						// let the injector's rejection loop exit before the caller reports
						// — the explicit try/catch also keeps the java transpilation
						// compilable (checked exceptions)
						MarkWsTestCompleted(exchange, url)
						panic(e)

					}(this)
				}
			}()
			// try block:
			for i := 0; i < GetArrayLength(expectedResults); i++ {

				r := <-CallExchangeMethodDynamically(exchange, method, input)
				if r.Err != nil {
					panic(r.Err)
				}
				result := r.Value
				// ws structures can be live typed objects (e.g. orderbooks) in some
				// runtimes — roundtrip through json so the deep-compare sees plain
				// dicts in every language
				var unifiedResult any = JsonParse(JsonStringify(result))
				this.AssertStaticResponseOutput(exchange, skipKeys, unifiedResult, GetValue(expectedResults, i))
			}
			return nil
		}(this)

	}
	MarkWsTestCompleted(exchange, url)

	ch <- ccxt.AsyncResult[any]{Value: true} // c# methods used with promiseAll need to return something
	return nil
}
